      $.put(V, $.call(this.nfdOf(), $.l(LCP)));
      $.put(NT, $.and($.shrU($.l(V), $.i(8)), $.i(7)));
      const part = (k: X): X => $.sel(I32, $.l(NT), $.aget(T, $.g(this.g.dec), $.add($.shrU($.l(V), $.i(11)), k)), $.l(LCP));
      const nParts = (): X => $.sel(I32, $.l(NT), $.l(NT), $.i(1));
