      $.put(W, $.add($.l(I), $.i(1)));
      $.for(P, $.add($.l(I), $.i(1)), $.l(END), () => {
        $.if($.ne(cc($.l(P)), $.i(-9)), () => {
          $.aset(T, $.l(C), $.l(W), c($.l(P)));
          $.aset(T, $.l(CC), $.l(W), cc($.l(P)));
          $.put(W, $.add($.l(W), $.i(1)));
        });
      });
